    GG.nextFrame() => now;
    // get mouse position
    GG.scene().camera().screenCoordToWorldPos(GWindow.mousePos(), 5) => vec3 end_target;
    // position on plane
    0 => end_target.z;
    // run IK solver
    fabrik(@(0, 0, 0), end_target, points, lengths);
    // update point locations
    for (int i; i < points.size(); i++) {
        points[i] => joints[i].pos;
    }
}

