//--
// name: Smacking.ck
// desc: class and process for tracking smack events from sudden motion sensor
//       only works with SMS-enabled laptops
//
// author: Rebecca Fiebrink + Ge Wang
// date: 2007
//--


// public class
public class Smacking
{
    static Event @ the_event;
}

// initialize separately (due to a bug)
new Event @=> Smacking.the_event;

// smack detection threshold (less -> more sensitive)
15 => int threshold;
// pol rate
.01::second => dur poll_rate;
// recover time (after smack detection)
.10::second => dur recover_time;

// instantiate a Hid object
Hid hi;
HidMsg msg;

// open tilt sensor
if( !hi.openTiltSensor() )
{
    <<< "tilt sensor unavailable", "" >>>;
    me.exit();
}

// "doh"
<<< "hit me!", "" >>>;

// remember
HidMsg last;
// initialize
hi.read( 9, 0, last );

// infinite event loop
while( true )
{
    // poll the tilt sensor, expect to get back 3 element array of ints
    hi.read( 9, 0, msg );

    // compute difference
    (Math.abs(msg.x - last.x) + Math.abs(msg.y - last.y) + Math.abs(msg.z - last.z)) => int diff;
    // check threshold
    if (diff > threshold) {
        // smack detected!
        // <<< "ouch!" >>>;
        // fire!
        Smacking.the_event.broadcast();
        // go
        recover_time => now;
    } else {
        // uncomment the following to dynamically calibrate the smack sensor
        // msg.x => last.x;    	    	
        // msg.y => last.y;
        // msg.z => last.z;

        // advance
        poll_rate => now;
    }
}

//--
// name: Tracking.ck
// desc: class and process for tracking a peak and amplitutde via FFT
//       the Tracking class can be accessed from external shreds
//
// author: Ge Wang + Rebecca Fiebrink
// date: 2007
//--


// public class
public class Tracking
{
    static float the_freq;
    static float the_gain;
    static Event @ the_event;
}

// initialize separately (due to a bug)
new Event @=> Tracking.the_event;

// analysis
adc => PoleZero dcblock => FFT fft => blackhole;

// set to block DC
.99 => dcblock.blockZero;
// set FFT params
2048 => fft.size;
// window
Windowing.hamming( fft.size() ) => fft.window;

// go for it
while( true )
{
    // take fft
    fft.upchuck() @=> UAnaBlob blob;

    // find peak
    0 => float max; float where;
    for( int i; i < blob.fvals().size()/8; i++ )
    {
        // compare
        if( blob.fvals()[i] > max )
        {
            // save
            blob.fvals()[i] => max;
            i => where;
        }
    }

    // set freq
    (where / fft.size() * (second / samp)) => Tracking.the_freq;
    // set gain
    (max / .5) => Tracking.the_gain;
    // clamp
    if( Tracking.the_gain > 1 )
        1 => Tracking.the_gain;
    // fire!
    Tracking.the_event.broadcast();

    // hop
    (fft.size()/4)::samp => now;
}

// our patch
SinOsc g => FFT fft => blackhole;
// synthesis
IFFT ifft => dac;
// set srate
second / samp => float srate;

// set parameters
1024 => fft.size;
// window
Windowing.hamming(512) => fft.window;
Windowing.hamming(512) => ifft.window;

// use this to hold contents
complex s[fft.size()/2];
// divide
int div;

// control loop
while( true )
{
    // set freq
    srate / fft.size() * div++ => g.freq;
    fft.size()/2 %=> div;

    // take fft
    fft.upchuck();
    // get contents
    fft.spectrum( s );
    // take ifft
    ifft.transform( s );

    // advance time
    256::samp => now;
}

// name: xcorr.ck
// desc: calculting how much delay is applied to a signal
// author: Curtis Ullerich

// signal source
SndBuf signal => dac;
// delayed signal
signal => DelayL delay => dac;
// load sound
"special:dope" => signal.read;
// randomize delay
Math.random2f(100, 400)$int => int delayMs;
// set delay
delayMs::ms => delay.max => delay.delay;
// set gain
0.8 => signal.gain;

// set analysis
signal => Flip f1 =^ XCorr xcorr => blackhole;
delay => Flip f2 =^ xcorr;
(second/samp)$int => int srate;

// will get bumped to the next power of two for the actual
// Fourier transform
signal.samples() + delayMs*srate/1000 => float size;
// FFT sizes
size$int => f1.size => f2.size;
// wait
signal.samples()::samp + delayMs::ms => now;
// analyze!
xcorr.upchuck();

// iterate
0 => int maxI;
for (0 => int i; i < size; i++)
{
    // look for max
    if (xcorr.fval(i) >= xcorr.fval(maxI)) {
        i => maxI;
    }
}

// print
<<< "    actual delay was", delayMs, "milliseconds" >>>;
<<< "calculated delay was", 1000*maxI/srate$float, "milliseconds" >>>;
// wait
1::second => now;

// name: xsynth-stereo.ck
// desc: a FFT-based cross-synthesizer (stereo delay edition)
//       => input X modulates a second input Y,
//          carried out in the frequency domain
//
// authors: Ge Wang
//          Celeste Betancur
//          Andrew Zhu Aday
//
// date: 2007 initial (really bad) version
//       2025 made less bad (and added stereo version)

// input x (mic)
adc => FFT X => blackhole;
// source two (to be connected below)
FFT Y => blackhole;
// synthesis
IFFT ifft => Delay dL => dac.left;
dL => Gain dLg => dL;
300::ms => dL.max => dL.delay;
.5 => dLg.gain;

ifft => Delay dR => dac.right;
dR => Gain dRg => dR;
450::ms => dR.max => dR.delay;
.5 => dRg.gain;

// input y
BlitSquare blt[6];
[ 40, 46, 52, 60, 64, 87] @=> int pitches[];
for( int i; i < blt.size(); i++ )
{
    blt[i] => Y;
    20 => blt[i].harmonics;
    pitches[i] => Std.mtof => blt[i].freq;
}

// set FFT size
1024 => X.size => Y.size => int FFT_SIZE;
// desired hop size
FFT_SIZE / 4 => int HOP_SIZE;
// set window and window size
Windowing.hann(FFT_SIZE) => X.window;
Windowing.hann(FFT_SIZE) => Y.window;
Windowing.hann(FFT_SIZE) => ifft.window;
// use this to hold contents
complex Z[FFT_SIZE/2];

// control loop
while( true )
{
    // take ffts
    X.upchuck();
    Y.upchuck();

    // multiply in frequency domain
    // NOTE: using input X's magnitude to modulate input Y's signal
    //       X and Y are NOT commutative
    for( int i; i < Z.size(); i++ )
        (X.cval(i)$polar).mag * Y.cval(i) => Z[i];

    // take ifft
    ifft.transform( Z );

    // advance time
    HOP_SIZE::samp => now;
}

