fun void keyboardListener(int device) {
    Hid hi;
    HidMsg msg;

    0x1e => int KEY_1;  // Keyboard 1 and !
    0x1f => int KEY_2;  // Keyboard 2 and @
    0x20 => int KEY_3;  // Keyboard 3 and #

    // open keyboard (get device number from command line)
    if( !hi.openKeyboard( device ) ) {
        cherr <= "keyboard " + device + " not found" <= IO.newline();
        me.exit();
    }
    <<< "keyboard '" + hi.name() + "' ready", "" >>>;

    while( true ) {
        hi => now;
        while( hi.recv( msg ) ) {
            if( msg.isButtonDown() ) {
                if (msg.key == KEY_1) {
                    <<< "switching to JCRev" >>>;
                    1.0 => jcRev.gain;
                    0.0 => nRev.gain;
                    0.0 => prcRev.gain;
                }

                if (msg.key == KEY_2) {
                    <<< "switching to NRev" >>>;
                    0.0 => jcRev.gain;
                    1.0 => nRev.gain;
                    0.0 => prcRev.gain;
                }

                if (msg.key == KEY_3) {
                    <<< "switching to PRCRev" >>>;
                    0.0 => jcRev.gain;
                    0.0 => nRev.gain;
                    1.0 => prcRev.gain;
                }

            }
        }
    }
} spork ~ keyboardListener(DEVICE_ID);

