        // broadcast to all shreds waiting on PULSE
        PULSE.broadcast();

        // increment tick count
        PULSE.tick++;
        // print
        cherr <= "."; cherr.flush();
        // if we reached the end of a measure
        if( PULSE.tick >= ticksPerMeasure )
        {
            // increment measure number
            PULSE.measure++;
            // reset tick count to 0
