//-----------------------------------------------------------------------------
// name: readme-LiSa1.ck
// desc: Live sampling utilities for ChucK
//
// the LiSa ugens allow realtime recording of audio to a buffer for
// various kinds of manipulation. Below is a simple example
// demonstrating the basic functionality of LiSa.
//
// See readme-LiSa2.ck for a command summary and instructions for
// doing multiple voice playback.
//
// author: Dan Trueman, 2007
//-----------------------------------------------------------------------------

// signal chain; record a sine wave, play it back
SinOsc s => LiSa saveme => dac;
// monitor the input
s => dac;

// alloc memory; required
6::second => saveme.duration;
// freq
440 => s.freq;
// gain
0.25 => s.gain;

// start recording input
saveme.record(1);
// let time pass for 2 seconds
.5::second => now;
// stop recording
saveme.record(0); 

// disconnect; stop monitoring input
s =< dac;

// start playing what was just recorded, with panning...
// set playback rate
saveme.rate(1.5);
// set pan (0 is hard left, 1 is hard right)
saveme.pan(0.0);
// start playing, with a ramp up
// (use saveme.play(1) to start playing without ramp)
saveme.rampUp(500::ms); 

// hang for a bit
500::ms => now;

// rampdown
// (use saveme.play(0) to stop playing without ramp)
saveme.rampDown( 500::ms );

// wait for ramp to finish
600::ms => now;

// bye bye

//--------------------------------------------------------------------
// name: readme-LiSa2.ck
// desc: Live Sampling (LiSa) utilities for ChucK
//
// author: Dan Trueman
// date: 2007
//
// to run (in command line chuck):
//     %> chuck readme-LiSa2.ck
//
// to run (in miniAudicle):
//     (just run it!)
//--------------------------------------------------------------------
// LiSa allows for multiple voice playback from a live-sampled buffer.
// Useful for granular sampling (a la [munger~] from PeRColate) and
// looping (a la LoopLoop, Jamman, Echoplex, etc....). The methods
// are overloaded, taking a "voice" number as a first arg. if no
// voice number is specified, LiSa assumes 0 => voice.
//
// Below is a simple example to show how to crossfade two voices.
// See also the LiSa_munger examples for other approaches.
//
// Below the example find a (lengthy) command summary.
//--------------------------------------------------------------------

// signal chain; record a sine wave, play it back
SinOsc s => Envelope e => LiSa10 loopme => dac;
// direct
s => e => dac;
// set frequency
440. => s.freq;
// set gain
0.25 => s.gain;

// print channel info
<<< "LiSa channels:", loopme.channels() >>>;

// allocate memory in LiSa
6::second => loopme.duration;

// play s for a bit
500::ms => now;

// sweep the freq for fun
Envelope pitchmod => blackhole;
pitchmod.duration( 2000::ms );
pitchmod.value( s.freq() );
pitchmod.target( 880.0 );

// confirm that the length of the buffer is what you expect
<<< "buffer duration = ", loopme.duration() / second >>>;

// set times for recording fade in/out and sample loop length
100::ms => dur recfadetime;
1000::ms => dur mylooplen;
// set envelope duration
e.duration( recfadetime );

// print
<<< "start recording input into LiSa...", "" >>>;
// start recording input; record 1 seconds worth
loopme.record(1);
// open envelope (can also do without the Envelope and use
// loopme.recramp(dur) to set a recording ramp)
e.keyOn();

// calcuate later
now + (mylooplen - recfadetime) => time later;
// go until now is later (or later)
while(now < later)
{
    // set frequency
    pitchmod.value() => s.freq;
    // advance time
    10::ms => now;
}
// close envelope
e.keyOff();
// let fade time pass
recfadetime => now;
// print
<<< "stop recording input into LiSa...", "" >>>;
// stop recording input
loopme.record(0);

// disconnect direct input...
s =< dac;
// print
<<< "disconnect sine and hanging out...", "" >>>;
// and hang out for a bit
1000::ms => now;

// now, manipulate the sample
// get a voicenumber; note that this voice won't actually be
// reserved until you play it
loopme.getVoice() => int voice1;

// we'll play voice 1 forward; then crossfade with voice 2 backwards
// set gain
loopme.voiceGain( voice1, .5 );
// set pan (hard left channel)
loopme.pan( voice1, 0 );
// play voice 1
loopme.play( voice1, 1 );
// print
<<< "playing LiSa voice 1 ( id:", voice1, ")" >>>;
// let time pass
(mylooplen - recfadetime) => now;

// just as voice 1 is going to fade, bring in voice 2
loopme.getVoice() => int voice2;
// set play rate to go backwards
loopme.rate( voice2, -1.0 );
// set play head at the end
loopme.playPos( voice2, mylooplen ); 
// set gain
loopme.voiceGain( voice2, 0.5 );
// set pan (hard right channel)
loopme.pan( voice2, 1 );
// play
loopme.play( voice2, 1 );
// print
<<< "playing LiSa voice 2 ( id:", voice2, ")" >>>;

// wait until voice 1 had finished fading...
recfadetime => now;
// turn off voice 1
loopme.play( voice1, 0 );
// print
<<< "stopping LiSa voice 1...", "" >>>;

// wait for voice 2 to finish
1000::ms => now;

// print
<<< "program ending...", "" >>>;

//--------------------------------------------------------------------
// LiSa Command Summary:
//
//  mylisa.duration(dur); required -- sets max length of buffer
//  mylisa.duration(); returns max length of buffer
//  mylisa.record(1/0); turn on/off recording into buffer
//  mylisa.getVoice() => voice (int); returns first free voice number
//  mylisa.maxVoices(int); sets maximum # of allowable voices
//  mylisa.play(voice, 1/0); turn on/off play for particular voice
//  mylisa.rampUp(voice, dur); turn on play for voice with ramp
//  mylisa.rampDown(voice, dur); ramp down voice and then turn off play
//  mylisa.rate(voice, float); sets play rate for "voice"
//  mylisa.playPos(voice, dur); sets playback position for "voice" within buffer
//  mylisa.playPos(voice); returns playback position for "voice"
//  mylisa.recordPos(dur); sets record position
//  mylisa.recordPos(); gets record position
//  mylisa.recRamp(dur); sets ramping for the edges of the record buffer
//  mylisa.loopStart(dur, voice); sets loopstart point for "voice"
//  mylisa.loopStart(voice); get loopstart
//  mylisa.loopEnd(voice, dur); sets loopend point for "voice"
//  mylisa.loopEnd(voice); gets loopend
//  mylisa.loop(voice, 1/0); turn on/off looping for "voice"
//  mylisa.loop(voice); get looping state
//  mylisa.bi(voice, 1/0); turn on/off bidirectional looping for "voice"
//  mylisa.bi(voice); get bi state
//  mylisa.voiceGain(voice, float); sets gain "voice"
//  mylisa.voiceGain(voice); gets gain for "voice"
//  mylisa.loopEndRec(dur); set looping end point for recording
//  mylisa.loopEndRec(); get ...
//  mylisa.feedback(float); set feedback amount [0,1] for recording
//  mylisa.feedback(); get...
//  mylisa.clear(); clear recording buffer
//  mylisa.pan(); returns pan value of voice 0
//  mylisa.pan(float where); pans voice 0 where can be [0., 7.], to place voice across LiSa's 8 outputs
//  mylisa.pan(int voice); returns pan value of voice
//  mylisa.pan(int voice, float where); pans specified voice where can be [0., 7.], to place voice across LiSa's 8 outputs
//
// Note that that LiSa defaults to mono;
// As of chuck 1.4.1.0 multi-channel LiSas can be instantiated
// using the following UGens:
//   LiSa2 (stereo)
//   LiSa4 (quad),
//   LiSa6 (6-channel, laptop orchestra edition)
//   LiSa8 (8-channel),
//   LiSa10 (10-channel, for compatibility)
//   LiSa16 (16-channel)
// The outputs of these LiSas can be sent to a multichannel dac, or
// simply to other ugens, if it is desirable to process the channels
// in different ways. These multiple channels are available
// regardless of whether the dac is running > 2 chans. LiSaX's
// multi-channel output can be manually connected through .chan(n).
//
// All of these commands should work without the "voice" arg;
// 0 => voice will be assumed see online documentation for most
// up-do-date listing...
//--------------------------------------------------------------------

//---------------------------------------------------------------------
// name: scream-o-matic.ck
// desc: using multiple LiSas for granular synthesis, to make a
//       continuous scream generator; based on the patch for
//       the augmented FlowBee interface (2014):
//       
//       "Suck-O-Phonic 6000: Augmented Flowbee Musical Interface"
//       https://www.youtube.com/watch?v=g3bkaljCVRs
//
// sound files used in this example:
//       https://chuck.stanford.edu/doc/examples/special/scream-o-matic/data/
//
// author: Alex Chechile
//         Spencer Salazar
//         Ge Wang (https://ccrma.stanford.edu/~ge/)
//---------------------------------------------------------------------
// change this for multi-channel screams
2 => int NUM_CHANNELS;
// per-channel components
NRev reverb[NUM_CHANNELS];
// DC blockers in case any input files has DC/low-freq bias
PoleZero dcblocker[NUM_CHANNELS];

// patch it
for( int i; i < NUM_CHANNELS; i++ )
{
    dcblocker[i] => reverb[i] => dac.chan(i);
    .99 => dcblocker[i].blockZero;
    .1 => reverb[i].mix;
}

// max lisa voices
30 => int LISA_MAX_VOICES;
// grain duration base
250::ms => dur GRAIN_DURATION_BASE;
// grain duration (in multiples of duration base)
6 => float GRAIN_DURATION_FACTOR;
// factor relating grain duration to ramp up/down time
.5 => float GRAIN_RAMP_FACTOR;
// playback rate
1 => float GRAIN_PLAY_RATE;
// grain rate factor (0 means no change)
.2 => float GRAIN_RATE_FACTOR;

// array of screams
LiSa @ lisa[0];
// load data and append to array
lisa << load( me.dir() + "data/scream-1.wav" );
lisa << load( me.dir() + "data/scream-2.wav" );
lisa << load( me.dir() + "data/scream-3.wav" );
lisa << load( me.dir() + "data/scream-4.wav" );
lisa << load( me.dir() + "data/scream-5.wav" );
lisa << load( me.dir() + "data/scream-6-lion.wav" );
// how many to use (remove the `-1` to include lion roar)
lisa.size()-1 => int NUM_LISA;

// connect and pan
for( int i; i < NUM_LISA; i++ )
{
    // connect lisa to audio output
    lisa[i] => dcblocker[i%NUM_CHANNELS];
}

// per-LiSa control shred; the arguments here can be adapted/replaced by
// other input parameters, e.g., from code/kb/mouse/gametrak
fun void go( LiSa @ lisa, float avgR, float varR, float avgT, float varT, dur T )
{
    while( true )
    {
        // fireGrain( LiSa @ lisa, float pos, float rate, dur T, float gain )
        fireGrain( lisa, 
            Math.random2f(.1,.9), Math.random2f(avgR-varR/2,avgR+varR/2), 
            Math.random2f(avgT-varT/2, avgT+varT/2)::ms, 1 );
        T => now;        
    }
}

// spork per-lisa shre
for( int i; i < NUM_LISA; i++ )
{
    // randomize each LiSa for now
    // play with these parameters; maybe randomize differently for different effect
    // go( LiSa @ lisa, float avgR, float varR, float avgT, float varT, dur T )
    spork ~ go( lisa[i], 1, .4, 800, 400, Math.random2f(300,500)::ms );
}

// time loop
while( true )
{ 
    for( int i; i < NUM_LISA; i++ )
    {
        // one of several place to map input (e.g., from kb/mouse/gametrak)
        .5 => lisa[i].gain;
    }

    10::ms => now;
}

// fire a grain
fun void fireGrain( LiSa @ lisa, float pos, float rate, dur T, float gain )
{
    // get diff time
    // gt.currTime - gt.lastTime => dur diffTime;
    GRAIN_DURATION_BASE => dur diffTime;
    // grain length
    diffTime * GRAIN_DURATION_FACTOR => dur grainLen;
    // ramp time
    grainLen * GRAIN_RAMP_FACTOR => dur rampTime;
    // a grain
    if( lisa != null && pos >= 0 )
        spork ~ grain( lisa, pos * lisa.duration(), grainLen, T/2, T/2, 
        rate * GRAIN_PLAY_RATE, gain );
}

// sporkee
fun void grain( LiSa @ lisa, dur pos, dur grainLen, dur rampUp, dur rampDown, float rate, float gain )
{
    // get a voice to use
    lisa.getVoice() => int voice;

    // if available
    if( voice > -1 )
    {
        // set rate
        lisa.rate( voice, rate );
        // set playhead
        lisa.playPos( voice, pos );
        // voice inga
        lisa.voiceGain( voice, gain );
        // ramp up
        lisa.rampUp( voice, rampUp );
        // wait
        (grainLen - rampUp) => now;
        // ramp down
        lisa.rampDown( voice, rampDown );
        // wait
        rampDown => now;
    }
}

// load file into a LiSa
fun LiSa load( string filename )
{
    // sound buffer
    SndBuf buffy;
    // load it
    filename => buffy.read;

    // new LiSa
    LiSa lisa;
    // set duration
    buffy.samples()::samp => lisa.duration;

    // transfer values from SndBuf to LiSa
    for( 0 => int i; i < buffy.samples(); i++ )
    {
        // args are sample value and sample index
        // (dur must be integral in samples)
        lisa.valueAt( buffy.valueAt(i), i::samp );        
    }

    // set LiSa parameters
    lisa.play( false );
    lisa.loop( false );
    lisa.maxVoices( LISA_MAX_VOICES );

    return lisa;
}

//--------------------------------------------------------------------
// name: twilight-granular-kb-interp.ck
// desc: Twilight (2013) granular synthesis instrument redux,
//       keyboard (interpolated) edition --
//       adapted from the original Gametrak-based instrument
//
// Twilight (2013) for laptop orchestra:
//       http://slork.stanford.edu/works/twilight/
//       https://www.youtube.com/watch?v=chA-4GRCb-I
//       https://vimeo.com/100624271
//
// author: Ge Wang (ge@ccrma.stanford.edu)
// date: initial instrument: Spring 2013
//       redux version: Summer 2014
//       keyboard version: Winter 2015
//
// usage (loads twilight-source.aiff by default):
//        chuck twilight-granular-kb
// usage (with argument):
//        chuck twilight-granular-kb:SOUND.WAV
//
// keyboard control (also see kb() below):
//       UP/DOWN -- grain position
//       LEFT/DOWN -- grain rate / tuning
//       ','/'.' -- grain size
//       '-'/'=' -- grain position random amount
//--------------------------------------------------------------------

// default filename (can be overwritten via input argument)
"twilight-granular.aiff" => string FILENAME;
// get file name, if one specified as input x0argument
if( me.args() > 0 ) me.arg(0) => FILENAME;

// overall volume
1 => float MAIN_VOLUME;
// grain duration base
50::ms => dur GRAIN_LENGTH;
