public class JacoBass extends Chugraph {
    // use Algorithm 1
    HnkyTonk b => Pan2 p => Chorus c => NRev r => outlet;
    0.04 => r.mix;

    [1,1,1,7] @=> int waveForms[];
    // [99,80,81,67] @=> int opGains[]; // from the actual patch, too bright
