Impulse imp => ResonZ rez2 => rev; // "kick drum"
9000 => rez.freq; 12 => rez.Q; 3.0 => rez.gain; // hi hat
100 => rez2.freq; 8 => rez2.Q;  // kick drum
.5 => rev.gain; // a volume knob

0.12::second => dur S;
0 => int beat;
0 => int meas; // 0 = flag to start,  > 0 = measure#
1 => int notDone;

