while( notDone ) {
    // do drums and keep track of song position
    spork ~ teenTown();
    for (1 => int meas; meas < 33; meas++)
    {
        300 => imp.next; // kick drum
        (0.001,0.12,0.0,0.001) => e.set; // hi hat closed
        1 => e.keyOn;
        S => now;
