    if( !kb.openKeyboard( device ) ) me.exit();
    <<< "keyboard '" + kb.name() + "' ready", "" >>>;
    while( true )
    {
        // wait on event
        kb => now;

        // get one or more messages
        while( kb.recv( kb_msg ) )
        {
            // check for action type
            if( kb_msg.isButtonDown() )
            {
                // <<< "down:", kb_msg.which, "(code)", kb_msg.key, "(usb key)", kb_msg.ascii, "(ascii)" >>>;
                kb_set_playhead(kb_msg.which);
                kb_set_rate(kb_msg.which);
            }

            else
            {
                //<<< "up:", msg.which, "(code)", msg.key, "(usb key)", msg.ascii, "(ascii)" >>>;
            }
        }
    }
}
spork ~ kb_listener();


fun void kb_set_playhead(int which)
{
    if (which == 39)    // 0 (number row) key
    {
        <<<"0 pressed">>>;
        player.pos(180.0);
    }
}

fun void kb_set_rate(int which)
{
    if(which == 29)     // z key
    {
        .1 -=> player.rate;
        <<<"rate:", player.rate>>>;
    }
    if(which == 27)     // x key
    {
        .1 +=> player.rate;
        <<<"rate:", player.rate>>>;
    }  
}


while(true)
{
    1::second => now;
}

//-----------------------------------------------------------------------------
// name: basic-instrument.ck
// desc: this example shows how to design a basic instrument and set it up for playback
//
// author: Kiran Bhat (https://ccrma.stanford.edu/~kvbhat/), Alex Han (https://ccrma.stanford.edu/~alexhan/)
//-----------------------------------------------------------------------------
@import "smuck"

// Create instrument(s) for playback
class basicInst extends ezInstrument
{
    // Set up signal chain
    //--------------------------------
    numVoices(10); // Allocate 10 voice polyphony for this instrument. Note: calling this function is important to tell the score player how many voices are available during playback
    SinOsc oscs[numVoices()];
    Gain g => outlet;                       // Chucking to outlet lets us connect our instrument to other signal chains after instantiation
    g.gain(0.1);
    for (0 => int i; i < numVoices(); i++)
    {
        oscs[i].gain(0);          // We want each osc to be silent before a note is played
        oscs[i] => g;
    }

    // Implement required noteOn and noteOff functions
    //--------------------------------

    // What our instrument does when a note is played (this function is called automatically by the score player)
    fun void noteOn(ezNote note, int voice) // noteOn and noteOff must have these arguments!
    {
        Std.mtof(note.pitch()) => oscs[voice].freq; // pitches are MIDI note numbers (e.g. 60 is middle C)
        note.velocity() => oscs[voice].gain; // ezNote velocities are float values 0.0-1.0
    }

    // What our instrument does when a note is released (this function is called automatically by the score player)
    fun void noteOff(ezNote note,int voice)
    {
        0 => oscs[voice].gain;
    }
}

// Create simple score
ezPart part0("a3 b c d e f g a");
ezPart part1("c5 d e f g a b c");
ezScore score;
score.add([part0, part1]);

// Create our instruments (1 for each part)
basicInst bass => dac;
basicInst treble => dac;

// Set the instruments for each part
ezScorePlayer player(score);
player.instruments([bass, treble]);

// Play the score
player.play();

// Let time pass until the score is finished playing
score.duration() => now;

//-----------------------------------------------------------------------------
// name: ezcc-basic.ck
// desc: Manual CC creation and playback with ezCC, measure.add(cc), instrument.cc()
// author: Alex Han
//-----------------------------------------------------------------------------
@import "smuck"

// Custom instrument that overrides cc() to handle CC events (ezDefaultInst prints to console)
class CCInst extends ezDefaultInst
{
    // Override cc() to modulate gain based on volume CC (CC7)
    fun void cc(ezCC cc)
    {
        if (cc.isCC() && cc.data1() == 7)
        {
            // Volume CC: scale 0-127 to gain
            cc.data2() / 127.0 => float g;
            bus.gain(g * 0.25);
        }
        // Also print for visibility
        <<< "CC: ch=", cc.channel(), " ctrl=", cc.data1(), " val=", cc.data2(), " onset=", cc.onset() >>>;
    }
}

// Build a short score with notes and CCs in the same measure
ezMeasure m("c4 e g c5");
// Add CCs: volume ramp, modulation at beat 2
ezCC.volume(0, 64, 0.0) @=> ezCC volStart;
ezCC.volume(0, 127, 2.0) @=> ezCC volEnd;
ezCC.modulation(0, 64, 1.0) @=> ezCC mod;
m.add([volStart, volEnd, mod]);
ezPart part;
part.add(m);
ezScore score;
score.add(part);

// Use our CC-aware instrument
CCInst inst => dac;
ezScorePlayer player(score);
player.instruments([inst]);

// Play and let run to completion
player.loop(true);
player.play();
eon => now;

