inputs << "a:cd:e";                      // 13
inputs << "a3:c:e:g a3:c:e:g";           // 14

// Repeats
inputs << "ax3 c d";                      // 15
inputs << "[a b c]x3 d e";                // 16
inputs << "a3:c:e:gx2";                   // 17

// Rests
inputs << "a r b c d";                    // 18

// Putting it all together
inputs << "k3f a3:c:e:gx2 [a b cs]x3 du euu"; // 19

// Set which string you want to test
0 => int index; 

