public class DrumsInst extends ezInstrument
{
    // define sound chain
    6 => int n_voices;
    numVoices(n_voices);
    SndBuf bufs[n_voices];
    Gain g => outlet;
    g.gain(0.6);
    for(int i; i < n_voices; i++)
    {
        bufs[i] => g;
    }

    // mapping midi numbers to drum sounds
    54+12 => int HIHAT;    
    41+12 => int RIDE_BELL;
    39+12 => int RIDE_TIP;
    27+12 => int SNARE;
    46+12 => int CRASH_1_EDGE;
    48+12 => int KICK;


    fun void noteOn(ezNote note, int voice)
    {
        note.pitch() => int drum_sound;
        note.velocity() => float drum_volume;

        // identify which drum sound
        string wav_file_name;
        if (drum_sound == HIHAT)
        {
            "../data/audio/drum_wavs/hihat.wav" => wav_file_name;
        }
        else if (drum_sound == RIDE_BELL)
        {
            "../data/audio/drum_wavs/ride_bell.wav" => wav_file_name;
        }
        else if (drum_sound == RIDE_TIP)
        {
            "../data/audio/drum_wavs/ride_tip.wav" => wav_file_name;
        }
        else if (drum_sound == SNARE)
        {
            "../data/audio/drum_wavs/snare.wav" => wav_file_name;
        }
        else if (drum_sound == KICK)
        {
            "../data/audio/drum_wavs/kick.wav" => wav_file_name;
        }
        else if (drum_sound == CRASH_1_EDGE)
        {
            "../data/audio/drum_wavs/crash_1_edge.wav" => wav_file_name;
        }
        else
        {
            <<< "DrumsVoice.ck: error, received invalid midi number for drums:", drum_sound >>>;
            "../data/audio/drum_wavs/crash_1_edge.wav" => wav_file_name;
        }

        // play drum sound file
        bufs[voice].read(wav_file_name);
        drum_volume => bufs[voice].gain;
    }

    fun void noteOff(int voice)
    {
        // Unused
    }
}

//-----------------------------------------------------------------------------
// name: releaseInst.ck
// desc: This ezInstrument demonstrates how to design instruments with long release
// times that may extend beyond the end of a note's duration.
//
// author: Alex Han (https://ccrma.stanford.edu/~alexhan/)
//-----------------------------------------------------------------------------
@import "smuck"

public class releaseInst extends ezInstrument
{
    numVoices(16);
    TriOsc oscs[numVoices()] => ADSR envs[numVoices()] => LPF lpf => outlet;

    2200 => lpf.freq;

    for(int i; i < numVoices(); i++)
    {
        envs[i].set(50::ms, 450::ms, 0.9, 2500::ms); // Set up an ADSR envelope with a 2.5 second release time
    }

    fun void noteOn(ezNote note, int voice)
    {
        Std.mtof(note.pitch()) => oscs[voice].freq;
        envs[voice].keyOn();
    }

    fun void noteOff(ezNote note, int voice)
    {
        envs[voice].keyOff();
        envs[voice].releaseTime() => now; // Allows time to pass after keyOff is called, letting the note release to happen
    }
}

//-----------------------------------------------------------------------------
// name: samplerInst.ck
// desc: This ezInstrument reads in an audio file and plays it back, repitched
// according to incoming ezNote pitches. It assumes the audio file is a one-shot
// sample with a "root note" pitch.
//
// author: Alex Han (https://ccrma.stanford.edu/~alexhan/)
//-----------------------------------------------------------------------------

@import "smuck"

public class samplerInst extends ezInstrument {
    // Set up signal chain
    numVoices(16);
    SndBuf bufs[numVoices()] => outlet;

    // Private variables
    string _filename;
    int _root;

    // Constructor
    fun sampleInst(string file) { filename(file); }

    // Set filename
    fun void filename(string filename) {
        filename => _filename;
        for (auto buf : bufs) {
            buf.read(_filename);
            buf.pos(buf.samples());
        }
    }

    // Get filename
    fun string filename() { return _filename; }

    // Set root note
    fun void root(int root) { root => _root; }

    // Get root note
    fun int root() { return _root; }

    // Convert semitone offset to frequency ratio for playback rate
    fun float transpose(int amount) { return Math.pow(2, amount / 12.0); }


    // Note on function
    fun void noteOn(ezNote note, int voice) {
        <<< "noteOn", voice, note.pitch() >>>;
        transpose((note.pitch() $ int)-_root) => bufs[voice].rate;
        note.velocity() => bufs[voice].gain;
        bufs[voice].pos(0);
    }

    // Note off function
    fun void noteOff(ezNote note, int voice) { 0.0 => bufs[voice].gain; }
}
